<div id="page-content" class="page-wrapper clearfix"><div class="card"><div class="page-title clearfix"><h4><i data-feather="truck" class="icon-16"></i> <?php echo esc($supplier->name); ?> <span class="badge <?php echo $supplier->status==='active'?'bg-success':'bg-secondary'; ?>"><?php echo $supplier->status==='active'?'Activo':'Inactivo'; ?></span><small class="text-muted d-block mt5">RFC: <?php echo esc($supplier->rfc ?: 'No informado'); ?></small></h4><div class="title-button-group"><a href="<?php echo get_uri('suppliers'); ?>" class="btn btn-default"><i data-feather="arrow-left" class="icon-16"></i> Volver</a><?php if($can_manage): echo modal_anchor(get_uri('suppliers/modal_form'),'<i data-feather="edit" class="icon-16"></i> Editar',['class'=>'btn btn-default','data-post-id'=>$supplier->id]); ?> <button class="btn btn-default supplier-toggle" data-id="<?php echo (int)$supplier->id; ?>"><?php echo $supplier->status==='active'?'Inactivar':'Activar'; ?></button><?php endif; ?></div></div>
<div class="card-body"><ul class="nav nav-tabs" role="tablist"><li class="nav-item"><button class="nav-link active" data-bs-toggle="tab" data-bs-target="#supplier-information">Información</button></li><?php if($can_view_costs): ?><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#supplier-products">Productos cotizados</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#supplier-history">Historial de costos</button></li><?php endif; ?></ul>
<div class="tab-content pt20"><div class="tab-pane fade show active" id="supplier-information"><div class="row"><div class="col-md-6"><p><strong>Contacto</strong><br><?php echo esc($supplier->contact_name?:'-'); ?></p><p><strong>Teléfono</strong><br><?php echo esc($supplier->phone?:'-'); ?></p><p><strong>Correo</strong><br><?php echo esc($supplier->email?:'-'); ?></p></div><div class="col-md-6"><strong>Notas</strong><p><?php echo nl2br(esc($supplier->notes?:'-')); ?></p></div></div></div>
<?php if($can_view_costs): ?><div class="tab-pane fade" id="supplier-products"><h5>Productos cotizados</h5><?php if($products): ?><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Producto</th><th>Último costo</th><th>Última fecha</th><th>Veces cotizado</th></tr></thead><tbody><?php foreach($products as$p): ?><tr><td><?php echo modal_anchor(get_uri('items/view'),esc($p->title),['data-post-id'=>$p->product_id,'title'=>'Producto']); ?></td><td><?php echo to_currency($p->last_cost); ?></td><td><?php echo esc(format_to_date($p->last_date,false)); ?></td><td><?php echo(int)$p->quote_count; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="alert alert-info">Este proveedor todavía no tiene productos con historial de cotización.<br><small>Las propuestas en borrador no generan registros históricos.</small><?php if($draft_assignments_count): ?><br><strong>Hay <?php echo(int)$draft_assignments_count; ?> partida(s) actualmente en borrador.</strong><?php endif; ?></div><?php endif; ?></div>
<div class="tab-pane fade" id="supplier-history"><h5>Historial de costos</h5><?php if($history): ?><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Fecha</th><th>Producto</th><th>Costo</th><th>Propuesta</th><th>Cliente</th><th>Precio de venta</th></tr></thead><tbody><?php foreach($history as$h): ?><tr><td><?php echo esc(format_to_date($h->quoted_at,false)); ?></td><td><?php echo esc($h->product_name); ?></td><td><?php echo to_currency($h->unit_cost); ?></td><td><a href="<?php echo get_uri('proposals/view/'.$h->proposal_id); ?>">#<?php echo(int)$h->proposal_id; ?></a></td><td><?php echo esc($h->company_name); ?></td><td><?php echo to_currency($h->sale_unit_price); ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="alert alert-info">No existe historial comercial formalizado todavía. Las propuestas en borrador no generan registros históricos.</div><?php endif; ?></div><?php endif; ?></div></div></div></div>
<script>$(function(){$('.supplier-toggle').on('click',function(){appAjaxRequest({url:'<?php echo get_uri('suppliers/toggle_status'); ?>',type:'POST',data:{id:$(this).data('id'),<?php echo json_encode(csrf_token()); ?>:<?php echo json_encode(csrf_hash()); ?>},success:function(){location.reload();}});});});</script>
